import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';
import { mockEquipments } from '../data/mockEquipments';
import EquipmentCard from '../components/EquipmentCard';
import AuthModal from '../components/AuthModal';
import BorrowModal from '../components/BorrowModal';

export default function Equipments() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  // ดึงคำค้นหาจาก URL Query String (ถ้ากดมาจากหน้าแรก)
  const queryParams = new URLSearchParams(location.search);
  const initialSearch = queryParams.get('search') || '';

  const [searchQuery, setSearchQuery] = useState(initialSearch);
  const [selectedCategory, setSelectedCategory] = useState('ทั้งหมด');
  const [selectedStatus, setSelectedStatus] = useState('ทั้งหมด');
  const [sortBy, setSortBy] = useState('default');

  const [authModalOpen, setAuthModalOpen] = useState(false);
  const [borrowModalOpen, setBorrowModalOpen] = useState(false);
  const [selectedEquipment, setSelectedEquipment] = useState(null);

  const categories = [
    { id: 'ทั้งหมด', label: '📦 ทั้งหมด' },
    { id: 'อุปกรณ์ถ่ายภาพ', label: '📷 อุปกรณ์ถ่ายภาพ' },
    { id: 'ไอที', label: '💻 ไอที & โน้ตบุ๊ก' },
    { id: 'กีฬา', label: '⚽ อุปกรณ์กีฬา' },
    { id: 'อื่นๆ', label: '🎸 อื่นๆ' }
  ];

  useEffect(() => {
    if (initialSearch) {
      setSearchQuery(initialSearch);
    }
  }, [initialSearch]);

  // กรองข้อมูลอุปกรณ์
  const filteredEquipments = mockEquipments
    .filter(item => {
      const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                            item.description.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesCategory = selectedCategory === 'ทั้งหมด' || item.category === selectedCategory;

      let matchesStatus = true;
      if (selectedStatus === 'มีของพร้อมยืม') {
        matchesStatus = item.availableStock > 0;
      } else if (selectedStatus === 'ของหมด') {
        matchesStatus = item.availableStock === 0;
      }

      return matchesSearch && matchesCategory && matchesStatus;
    })
    .sort((a, b) => {
      if (sortBy === 'name') return a.name.localeCompare(b.name);
      if (sortBy === 'stock') return b.availableStock - a.availableStock;
      return 0;
    });

  const handleBorrowClick = (equipment) => {
    if (!user || user.role === 'guest') {
      setAuthModalOpen(true);
    } else {
      setSelectedEquipment(equipment);
      setBorrowModalOpen(true);
    }
  };

  const handleResetFilter = () => {
    setSearchQuery('');
    setSelectedCategory('ทั้งหมด');
    setSelectedStatus('ทั้งหมด');
    setSortBy('default');
    navigate('/equipments');
  };

  return (
    <div style={{ maxWidth: '1240px', margin: '40px auto', padding: '0 20px' }}>

      {/* Header Section */}
      <div style={{ marginBottom: '32px' }}>
        <h2 style={{ fontSize: '30px', color: '#0F172A', margin: '0 0 8px 0', fontWeight: '900', letterSpacing: '-0.5px' }}>
          📦 คลังอุปกรณ์ทั้งหมด (khongunai Tracker)
        </h2>
        <p style={{ color: '#64748B', fontSize: '15px', margin: 0 }}>
          ค้นหา เช็กตำแหน่งสต็อก และส่งคำขอยืมอุปกรณ์ได้รวดเร็วทันที
        </p>
      </div>

      {/* 🔍 Search & Filter Card Panel */}
      <div style={{
        background: '#FFFFFF',
        padding: '24px',
        borderRadius: '24px',
        border: '1px solid #E2E8F0',
        boxShadow: '0 10px 30px rgba(15, 23, 42, 0.04)',
        marginBottom: '32px'
      }}>

        {/* Row 1: ช่องค้นหาหลัก & ตัวกรองสถานะ/เรียงลำดับ */}
        <div style={{ display: 'flex', gap: '16px', flexWrap: 'wrap', marginBottom: '20px' }}>
          <div style={{ flex: '1 1 320px', position: 'relative' }}>
            <input 
              type="text"
              placeholder="🔍 พิมพ์ชื่ออุปกรณ์ หรือคำอธิบายที่ต้องการค้นหา..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              style={{
                width: '100%',
                padding: '14px 18px',
                borderRadius: '14px',
                border: '1px solid #CBD5E1',
                fontSize: '15px',
                outline: 'none',
                background: '#F8FAFC',
                boxSizing: 'border-box'
              }}
            />
            {searchQuery && (
              <button 
                onClick={() => setSearchQuery('')}
                style={{ position: 'absolute', right: '14px', top: '50%', transform: 'translateY(-50%)', border: 'none', background: 'none', color: '#94A3B8', cursor: 'pointer', fontSize: '16px' }}
              >
                ✕
              </button>
            )}
          </div>

          <div style={{ display: 'flex', gap: '12px', flexWrap: 'wrap' }}>
            <select
              value={selectedStatus}
              onChange={(e) => setSelectedStatus(e.target.value)}
              style={{
                padding: '12px 16px',
                borderRadius: '14px',
                border: '1px solid #CBD5E1',
                fontSize: '14px',
                background: '#F8FAFC',
                color: '#0F172A',
                fontWeight: '600',
                cursor: 'pointer',
                outline: 'none'
              }}
            >
              <option value="ทั้งหมด">🔘 ทุกสถานะ</option>
              <option value="มีของพร้อมยืม">🟢 พร้อมยืมเท่านั้น</option>
              <option value="ของหมด">🔴 ของหมดชั่วคราว</option>
            </select>

            <select
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value)}
              style={{
                padding: '12px 16px',
                borderRadius: '14px',
                border: '1px solid #CBD5E1',
                fontSize: '14px',
                background: '#F8FAFC',
                color: '#0F172A',
                fontWeight: '600',
                cursor: 'pointer',
                outline: 'none'
              }}
            >
              <option value="default">↕️ เรียงตามดั้งเดิม</option>
              <option value="stock">🔥 พร้อมยืมมากสุด</option>
              <option value="name">🔤 เรียงตามชื่อ (A-Z)</option>
            </select>
          </div>
        </div>

        {/* Row 2: Category Pills Bar (แท็บหมวดหมู่แบบเลือกง่าย) */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px', flexWrap: 'wrap', borderTop: '1px solid #F1F5F9', paddingTop: '16px' }}>
          <span style={{ fontSize: '13px', fontWeight: '700', color: '#64748B', marginRight: '6px' }}>หมวดหมู่:</span>
          {categories.map((cat) => {
            const isActive = selectedCategory === cat.id;
            return (
              <button
                key={cat.id}
                onClick={() => setSelectedCategory(cat.id)}
                style={{
                  background: isActive ? 'linear-gradient(135deg, #0284C7 0%, #38BDF8 100%)' : '#F1F5F9',
                  color: isActive ? '#FFFFFF' : '#475569',
                  border: 'none',
                  padding: '8px 18px',
                  borderRadius: '20px',
                  fontSize: '13px',
                  fontWeight: isActive ? '800' : '600',
                  cursor: 'pointer',
                  boxShadow: isActive ? '0 4px 12px rgba(56, 189, 248, 0.3)' : 'none',
                  transition: 'all 0.2s'
                }}
              >
                {cat.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* Result Status Bar */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px' }}>
        <p style={{ margin: 0, color: '#475569', fontSize: '14px', fontWeight: '600' }}>
          พบอุปกรณ์ทั้งหมด <strong style={{ color: '#0284C7', fontSize: '16px' }}>{filteredEquipments.length}</strong> รายการ
        </p>

        {(searchQuery || selectedCategory !== 'ทั้งหมด' || selectedStatus !== 'ทั้งหมด' || sortBy !== 'default') && (
          <button 
            onClick={handleResetFilter}
            style={{ background: 'none', border: 'none', color: '#EF4444', fontWeight: '700', fontSize: '13px', cursor: 'pointer' }}
          >
            🔄 ล้างการค้นหาทั้งหมด
          </button>
        )}
      </div>

      {/* Grid แสดงการ์ดอุปกรณ์ */}
      {filteredEquipments.length > 0 ? (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: '24px' }}>
          {filteredEquipments.map((equipment) => (
            <div 
              key={equipment.id} 
              onClick={() => navigate(`/equipment/${equipment.id}`)} 
              style={{ cursor: 'pointer' }}
            >
              <EquipmentCard equipment={equipment} onBorrow={handleBorrowClick} />
            </div>
          ))}
        </div>
      ) : (
        <div style={{ textAlign: 'center', padding: '80px 20px', background: '#FFFFFF', borderRadius: '24px', border: '1px solid #E2E8F0', color: '#64748B' }}>
          <span style={{ fontSize: '56px', display: 'block', marginBottom: '16px' }}>🔍</span>
          <h3 style={{ margin: '0 0 8px 0', color: '#0F172A', fontSize: '20px' }}>ไม่พบอุปกรณ์ตรงตามเงื่อนไขที่ค้นหา</h3>
          <p style={{ margin: '0 0 20px 0', fontSize: '14px' }}>ลองพิมพ์คำค้นหาอื่น หรือล้างตัวกรองเพื่อดูรายการทั้งหมด</p>
          <button 
            onClick={handleResetFilter}
            style={{ background: '#0284C7', color: '#FFF', border: 'none', padding: '10px 22px', borderRadius: '12px', fontWeight: '700', cursor: 'pointer', fontSize: '14px' }}
          >
            แสดงอุปกรณ์ทั้งหมด
          </button>
        </div>
      )}

      {/* Modals */}
      <AuthModal isOpen={authModalOpen} onClose={() => setAuthModalOpen(false)} />
      <BorrowModal isOpen={borrowModalOpen} onClose={() => setBorrowModalOpen(false)} equipment={selectedEquipment} />
    </div>
  );
}
